import{J as e,dt as t,j as n,q as r}from"./chunks/framework.767A_6fc.js";import"./chunks/assets.Dg-KBxrH.js";var i=JSON.parse(`{"title":"签到类型","description":"","frontmatter":{},"headers":[],"relativePath":"guide/type.md","filePath":"guide/type.md","lastUpdated":1782390088000}`),a={name:`guide/type.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="签到类型" tabindex="-1">签到类型 <a class="header-anchor" href="#签到类型" aria-label="Permalink to “签到类型”">​</a></h1><h2 id="课程、班级、群聊的区别" tabindex="-1">课程、班级、群聊的区别 <a class="header-anchor" href="#课程、班级、群聊的区别" aria-label="Permalink to “课程、班级、群聊的区别”">​</a></h2><p>打开学习通 App 的聊天页，课程是绿色图标，班级是黄色图标，群聊是学生头像拼接。</p><img src="/image/guide/%E5%88%86%E8%BE%A8%E7%AD%BE%E5%88%B0%E7%B1%BB%E5%9E%8B.png" style="width:min(60vw, 300px);"><details class="details custom-block"><summary>怎么签？（课程、班级、群聊签到都能搞定哦~）</summary><p><strong>1. 课程签到、班级签到</strong></p><p>直接在【课程学习】独自完成除二维码以外的签到类型，二维码需要同学去教室扫。班级签到本质是隐藏了课程入口的课程签到。</p><p><strong>2. 群聊签到</strong></p><p>在【实时学习】中监听签到通知，可独自完成各种类型的签到。</p></details><h2 id="课程签到的类型" tabindex="-1">课程签到的类型 <a class="header-anchor" href="#课程签到的类型" aria-label="Permalink to “课程签到的类型”">​</a></h2><p><img src="/image/guide/%E5%8F%91%E5%B8%83%E7%AD%BE%E5%88%B0%E7%B1%BB%E5%9E%8B.png" alt="签到类型辨别" width="3680" height="1280"></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>怎么签</th></tr></thead><tbody><tr><td>二维码签到</td><td>过期二维码漏洞已在 2023年4月8号 被学习通官方修复。截止目前没人能破解过期二维码签到。<br>二维码解码后是链接，例如：<a href="https://mobilelearn.chaoxing.com/widget/sign/e?id=80001231452&amp;enc=FACDD34DBC291EE176%EF%BC%8C%E5%8C%85%E5%90%AB" target="_blank" rel="noreferrer">https://mobilelearn.chaoxing.com/widget/sign/e?id=80001231452&amp;enc=FACDD34DBC291EE176，包含</a> id 和 enc 参数，enc 每 10 秒无规律变化一次。</td><td>点击 <strong>扫码学习</strong> 就可以扫码签到；若教师设置位置限制，可地图选点签到。<br>已自动绕过 “同一设备不能重复签到” 的限制。<br>PS：点击 “请人帮忙” 可以快捷把账号密码分享给同学帮你签。</td></tr><tr><td>位置签到</td><td>不会触发 “使用作弊工具” 提示。开发者已有应对策略，教师端仅显示正常签到记录。</td><td>地图选点，可自行修改签到位置文本。会员用户可获取教师设置的位置。<br>只要坐标对了，你填 “学园都市” 都能签上。</td></tr><tr><td>手势签到 / 签到码签到</td><td>签到码是 4-8 位的数字，不是二维码。</td><td>点击自动获取，即可获得签到码、手势图，然后点立即签到。</td></tr><tr><td>图片签到</td><td>会员用户可一键借用同学照片签到。</td><td>用户可上传任意图片进行签到。<br>不上传图片也会签到成功，但图片缺失。</td></tr></tbody></table><h2 id="签到的结果" tabindex="-1">签到的结果 <a class="header-anchor" href="#签到的结果" aria-label="Permalink to “签到的结果”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>部分同学分不清【1.未签】和【2.缺勤】，缺勤是你老师手动设置的！</p></div><table tabindex="0"><thead><tr><th style="text-align:center;">1. 未签</th><th style="text-align:center;">2. 缺勤</th><th style="text-align:center;">3. 教师代签</th><th style="text-align:center;">4. 虚拟定位</th><th style="text-align:center;">5. 已签</th></tr></thead><tbody><tr><td style="text-align:center;">如果没签到，显示的是这个</td><td style="text-align:center;">教师手动设置的</td><td style="text-align:center;"></td><td style="text-align:center;">v3 小程序支持自动绕过</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;"><img src="/image/result/%E6%9C%AA%E7%AD%BE.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E7%BC%BA%E5%8B%A4.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E6%95%99%E5%B8%88%E4%BB%A3%E7%AD%BE.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E8%99%9A%E6%8B%9F%E5%AE%9A%E4%BD%8D.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E5%B7%B2%E7%AD%BE.png" style="width:min(15vw, 160px);"></td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:center;">6. 事假</th><th style="text-align:center;">7. 病假</th><th style="text-align:center;">8. 公假</th><th style="text-align:center;">9. 迟到</th><th style="text-align:center;">10. 早退</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="/image/result/%E4%BA%8B%E5%81%87.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E7%97%85%E5%81%87.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E5%85%AC%E5%81%87.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E8%BF%9F%E5%88%B0.png" style="width:min(15vw, 160px);"></td><td style="text-align:center;"><img src="/image/result/%E6%97%A9%E9%80%80.png" style="width:min(15vw, 160px);"></td></tr></tbody></table>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};